      sSkillArg.nY = nYValue;
      sSkillArg.nUnitX = anYOffsets[nByteIdx] + sSkillArg.nX;
      sSkillArg.nUnitY = anYOffsets[nByteIdx + 6] + sSkillArg.nY;
      sSkillArg.pOwner = pPlayer;
      sSkillArg.pMissile = pUnit;
